from langchain.tools import Tool

# 定义工具
def get_character_info(character_name):
    # 调用游戏 API 获取角色信息
    return {
        "name": character_name,
        "element": "雷",
        "weapon": "长柄武器"
    }

character_tool = Tool(
    name="查询角色信息",
    func=get_character_info,
    description="查询原神角色的基础信息,包括元素、武器类型等"
)

# 使用(后面会讲如何让 AI 自动调用)
result = character_tool.run("雷电将军")

